text:
&:not([disabled]) {
  &:hover {
    background-color: var(--toolbarbutton-background-color-hover);
    border-color: var(--toolbarbutton-hover-bordercolor);
    box-shadow: var(--toolbarbutton-hover-boxshadow);
  }

  &:is([open="true"], [checked], :hover:active) {
    background-color: var(--toolbarbutton-checked-background);
    border-color: var(--toolbarbutton-active-bordercolor);
    box-shadow: var(--toolbarbutton-active-boxshadow);
  }

  &:is([open="true"], :hover:active) {
    background-color: var(--toolbarbutton-background-color-active) !important;
  }
}

&[wantdropmarker="true"] {
  background-image: var(--icon-nav-down-sm);
  background-repeat: no-repeat;
  background-position: calc(100% - 3px) center;
  padding-inline-end: 18px;

  &:-moz-locale-dir(rtl) {
    background-position-x: 3px;
  }
}

&[disabled] {
  opacity: 0.4;
}
